ALTER TABLE shop_products ADD COLUMN source_reference VARCHAR(1000) NULL;
ALTER TABLE shop_products ADD COLUMN trend_signal VARCHAR(500) NULL;

ON DUPLICATE KEY UPDATE
  name=VALUES(name),description=VALUES(description),price=VALUES(price),compare_at_price=VALUES(compare_at_price),image_url=VALUES(image_url),colors=VALUES(colors),sizes=VALUES(sizes),badge=VALUES(badge),inventory=VALUES(inventory),status=VALUES(status),featured=VALUES(featured),source_reference=VALUES(source_reference),trend_signal=VALUES(trend_signal);
